mapper.select:
select b.id, b.title, b.first_picture, b.create_time, b.update_time, b.is_published, b.is_recommend, b.is_appreciation, b.is_comment_enabled, b.is_top, b.password, b.status, b.words, b.read_time, c.id as category_id, c.category_name from blog as b left join category as c on b.category_id=c.id
b.status='DRAFT'
and b.title like #{titlePattern}
and b.category_id=#{categoryId}
